// Safely parse all three agent outputs.
// Agents sometimes wrap JSON in markdown fences despite instructions.

function parseAgent(raw, label) {
  if (raw === undefined || raw === null) {
    throw new Error(`${label}: no output received`);
  }
  if (typeof raw === 'object') return raw;

  let text = String(raw).trim();
  text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

  // grab the outermost JSON object if there is stray prose around it
  const start = text.indexOf('{');
  const end   = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    text = text.slice(start, end + 1);
  }

  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error(`${label}: could not parse JSON. Raw output was: ${String(raw).slice(0, 300)}`);
  }
}

const idea    = parseAgent($('Agent 1 - Strategist').first().json.output,  'Agent 1');
const caption = parseAgent($('Agent 2 - Copywriter').first().json.output,  'Agent 2');
const image   = parseAgent($('Agent 3 - Image Prompt').first().json.output, 'Agent 3');

// Build the final caption with hashtags appended
const tags = (caption.hashtags || [])
  .map(t => '#' + String(t).replace(/^#/, '').trim())
  .join(' ');

const finalCaption = `${caption.caption}\n\n${tags}`;

return [{
  json: {
    date:          $now.setZone('Asia/Karachi').toFormat('yyyy-LL-dd'),
    angle:         idea.angle          || '',
    topic:         idea.topic          || '',
    hook:          idea.hook           || '',
    key_points:    (idea.key_points || []).join(' | '),
    hook_line:     caption.hook_line   || '',
    caption:       caption.caption     || '',
    hashtags:      tags,
    final_caption: finalCaption,
    word_count:    caption.word_count  || 0,
    image_prompt:  image.image_prompt  || '',
    image_style:   image.style         || '',
    alt_text:      image.alt_text      || ''
  }
}];
